KEYMAP = {"imp": "impact", "fix": "proposed_correction", "pref": "preferred_and_why", "need": "required_evidence_or_resource",
          "acc": "acceptance_criteria", "test": "closure_tests", "dep": "dependencies", "alt": "alternatives",
          "evidence": "evidence", "reference": "reference"}


def main() -> int:
    rows = [dict(zip(FIELDS, r)) for r in R]
    for r in rows:
        for k, v in S.get(r["issue_id"], {}).items():
            if not r[KEYMAP[k]]:
                r[KEYMAP[k]] = v
        for f in ("dependencies", "alternatives"):
            if not r[f]:
                r[f] = "none"
    empty = [(r["issue_id"], f) for r in rows for f in FIELDS if not str(r[f]).strip()]
    if empty:
        raise SystemExit(f"required fields empty: {empty}")
    ids = [r["issue_id"] for r in rows]
    assert len(ids) == len(set(ids)), "duplicate issue ids"
    for r in rows:
        assert r["severity"] in {"CRITICAL", "HIGH", "MEDIUM", "LOW"}, r["issue_id"]
        assert r["status"] in {"FIXED", "PARTIALLY_FIXED", "UNRESOLVED", "BLOCKED", "NOT_VERIFIED"}, r["issue_id"]
        assert r["root_cause"] in {"CONFIRMED", "LIKELY", "UNKNOWN"}, r["issue_id"]
    with OUT.open("w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=FIELDS, lineterminator="\n")
        w.writeheader()
        w.writerows(rows)
    print(len(rows), "issues written")
    return 0


if __name__ == "__main__":
    sys.exit(main())
